    /**
     * List all disputes
     * <p>Returns a list of Issuing <code>Dispute</code> objects. The objects are sorted in descending order by creation date, with the most recently created object appearing first.</p>
     * @param created Only return Issuing disputes that were created during the given date interval.
     * @param endingBefore A cursor for use in pagination. `ending_before` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, starting with `obj_bar`, your subsequent call can include `ending_before=obj_bar` in order to fetch the previous page of the list.
     * @param expand Specifies which fields in the response should be expanded.
     * @param limit A limit on the number of objects to be returned. Limit can range between 1 and 100, and the default is 10.
     * @param startingAfter A cursor for use in pagination. `starting_after` is an object ID that defines your place in the list. For instance, if you make a list request and receive 100 objects, ending with `obj_foo`, your subsequent call can include `starting_after=obj_foo` in order to fetch the next page of the list.
     * @param status Select Issuing disputes with the given status.
     * @param transaction Select the Issuing dispute for the given transaction.
     * @param formData
     * @returns any Successful response.
     * @returns error Error response.
     * @throws ApiError
     */
    public static getIssuingDisputes(
        created?: ({
            gt?: number;
            gte?: number;
            lt?: number;
            lte?: number;
        } | number),
        endingBefore?: string,
        expand?: Array<string>,
        limit?: number,
        startingAfter?: string,
        status?: 'expired' | 'lost' | 'submitted' | 'unsubmitted' | 'won',
        transaction?: string,
        formData?: any,
    ): CancelablePromise<{
        data: Array<issuing_dispute>;
        /**
         * True if this list has another page of items after this one that can be fetched.
         */
        has_more: boolean;
        /**
         * String representing the object's type. Objects of the same type share the same value. Always has the value `list`.
         */
        object: 'list';
        /**
         * The URL where this list can be accessed.
         */
        url: string;
    } | error> {
        return __request(OpenAPI, {
            method: 'GET',
            url: '/v1/issuing/disputes',
            query: {
                'created': created,
                'ending_before': endingBefore,
                'expand': expand,
                'limit': limit,
                'starting_after': startingAfter,
                'status': status,
                'transaction': transaction,
            },
            formData: formData,
            mediaType: 'application/x-www-form-urlencoded',
        });
    }
